            AF <= AF_TAB[({IR, STATE[2:0]})];
            XT <= XT_TAB[({IR, STATE[2:0]})];
            SN <= SUCC_TAB[({IR, STATE[2:0]})];
         end
      end
   end

   assign M = {XT[24:17], XT[16:11], XT[10], XT[9], XT[8], XT[7:0], ALUFlags, MI.stateCtrl, MI.addrBus, MI.addrInc, MI.muxCtrl, MI.addrCtrl, MI.loadPC, MI.loadSP, MI.regAXY, MI.loadP, MI.loadT, MI.loadDKB, MI.busCtrl, MI.byteSel, MI.outBus, MI.va};

